CREATE TABLE roles (id BIGINT PRIMARY KEY AUTO_INCREMENT, code VARCHAR(40) NOT NULL UNIQUE, description VARCHAR(150) NOT NULL);
CREATE TABLE users (id BINARY(16) PRIMARY KEY, email VARCHAR(254) NOT NULL UNIQUE, full_name VARCHAR(150) NOT NULL, password_hash VARCHAR(100) NOT NULL, enabled BOOLEAN NOT NULL DEFAULT FALSE, mfa_enabled BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE user_roles (user_id BINARY(16) NOT NULL, role_id BIGINT NOT NULL, PRIMARY KEY(user_id,role_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(role_id) REFERENCES roles(id));
CREATE TABLE audit_events (id BIGINT PRIMARY KEY AUTO_INCREMENT, occurred_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, actor_id BINARY(16) NULL, action VARCHAR(100) NOT NULL, entity_type VARCHAR(60) NOT NULL, entity_id VARCHAR(80) NULL, ip_hash CHAR(64) NULL, details JSON NULL, INDEX idx_audit_time(occurred_at), FOREIGN KEY(actor_id) REFERENCES users(id));
